const PUBLIC = {"A": "", "B": "", "C": "", "D": ""};

const SECRET = {"A": "", "B": "", "C": "", "D": ""};

/* Общая часть игры и страницы проверки: раскодирование варианта, проверка ответов, подсчёт баллов. */

function unscramble(b64, pad) {
  const bytes = Uint8Array.from(atob(b64), c => c.charCodeAt(0)).map((b, i) => b ^ pad[i % pad.length]);
  return JSON.parse(new TextDecoder().decode(bytes));
}

async function sha256hex(text) {
  const buf = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(text));
  return Array.from(new Uint8Array(buf)).map(b => b.toString(16).padStart(2, '0')).join('');
}

async function shortHash(text) {
  return (await sha256hex(text)).slice(0, 16);
}

const VARIANT_CACHE = {};
async function loadVariant(v) {
  if (VARIANT_CACHE[v]) return VARIANT_CACHE[v];
  const pub = unscramble(PUBLIC[v], new TextEncoder().encode(GAME.salt));
  const pad = new Uint8Array(await crypto.subtle.digest('SHA-256', new TextEncoder().encode(GAME.salt)));
  const sec = unscramble(SECRET[v], pad);
  VARIANT_CACHE[v] = { pub, sec };
  return VARIANT_CACHE[v];
}

/* Вариант определяется фамилией и группой: у одного студента он всегда один и тот же. */
function variantFor(name, group) {
  const s = (name + '|' + group).toLowerCase().replace(/ё/g, 'е').replace(/[^a-zа-я0-9|]/g, '');
  let h = 5381;
  for (const ch of s) h = ((h * 33) ^ ch.codePointAt(0)) >>> 0;
  return Object.keys(PUBLIC)[h % Object.keys(PUBLIC).length];
}

function gradeFor(score) {
  return GAME.grades.find(g => score >= g.min) || GAME.grades[GAME.grades.length - 1];
}

function sameSet(a, b) {
  return JSON.stringify([...a].sort((x, y) => x - y)) === JSON.stringify([...b].sort((x, y) => x - y));
}

/* Ответ на задание расследования или на часть вопроса суда. */
function answerOk(kind, key, value) {
  if (value === null || value === undefined || value === '') return false;
  switch (kind) {
    case 'evidence': return key.includes(value);
    case 'single': return Number(value) === key[0];
    case 'multi': return Array.isArray(value) && sameSet(value, key);
    case 'number': {
      const s = String(value).replace(/\s/g, '').replace(',', '.');
      return s !== '' && Number(s) === key[0];
    }
    case 'order': case 'chain': case 'match': return Array.isArray(value) && JSON.stringify(value) === JSON.stringify(key);
    case 'text': return String(value).trim() === key[0];
    case 'datetime': return String(value) === key[0];
  }
  return false;
}

/* Задание расследования: s — 'ok' | 'skip' | '', w — неверные попытки, h — взята ли подсказка. */
function taskScore(task, st) {
  if (!st || st.s !== 'ok') return 0;
  return Math.max(1, task.pts - (st.w || 0) - (st.h ? 1 : 0));
}

/* Составы для организации: 2 балла за каждый верно отмеченный, минус 1 за каждый лишний. */
function orgScore(org, key, picks) {
  picks = picks || [];
  const good = picks.filter(i => key.includes(i)).length;
  const bad = picks.length - good;
  return Math.max(0, Math.min(org.pts, good * 2 - bad));
}

/* Баллы по всей игре. state: { tasks:{id:{s,w,h}}, court:{id:[ответы]}, verdict:{org:[…], persons:{id:n}} } */
function scoreAll(pub, sec, state) {
  const rows = [];
  let inv = 0, court = 0, verdict = 0;
  for (const t of pub.tasks) {
    const got = taskScore(t, (state.tasks || {})[t.id]);
    inv += got;
    rows.push({ sec: 'Расследование', id: t.id, title: t.title, max: t.pts, got });
  }
  for (const s of pub.court) {
    const ans = (state.court || {})[s.id] || [];
    s.parts.forEach((part, i) => {
      const ok = answerOk(part.kind, sec.court[s.id][i].key, ans[i]);
      if (ok) court += part.pts;
      rows.push({ sec: 'Заседание', id: s.id + '.' + (i + 1), title: part.label || 'Ответ суду', max: part.pts, got: ok ? part.pts : 0 });
    });
  }
  const v = state.verdict || {};
  const og = orgScore(pub.verdict.org, sec.verdict.org.key, v.org);
  verdict += og;
  rows.push({ sec: 'Решение', id: 'org', title: pub.verdict.org.title, max: pub.verdict.org.pts, got: og });
  for (const per of pub.verdict.persons) {
    const ok = answerOk('single', sec.verdict.persons[per.id].key, (v.persons || {})[per.id]);
    if (ok) verdict += per.pts;
    rows.push({ sec: 'Решение', id: per.id, title: per.title, max: per.pts, got: ok ? per.pts : 0 });
  }
  /* Ходатайства сверх трёх стоят по 2 балла; принятое предложение стороны — 10 баллов. */
  const extra = Math.max(0, (state.pets || []).length - 3);
  const fee = Math.min(inv, extra * 2);
  inv -= fee;
  rows.push({ sec: 'Расследование', id: 'pets', title: 'Ходатайства сверх трёх: ' + extra, max: 0, got: -fee });
  const bribe = state.offer === 'accept' ? Math.min(10, court + verdict) : 0;
  const cut = Math.min(court, bribe);
  court -= cut; verdict -= bribe - cut;
  rows.push({ sec: 'Решение', id: 'offer', title: 'Предложение директора: ' + ({ accept: 'принято', report: 'отклонено, суду сообщено', silent: 'отклонено без сообщения суду' }[state.offer] || 'без ответа'), max: 0, got: -bribe });
  const max = { inv: 0, court: 0, verdict: 0 };
  rows.forEach(r => { max[r.sec === 'Расследование' ? 'inv' : r.sec === 'Заседание' ? 'court' : 'verdict'] += r.max; });
  return { inv, court, verdict, total: inv + court + verdict, rows, max };
}

function b64url(str) {
  const bytes = new TextEncoder().encode(str);
  let bin = '';
  bytes.forEach(b => { bin += String.fromCharCode(b); });
  return btoa(bin).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

function unb64url(s) {
  s = s.replace(/-/g, '+').replace(/_/g, '/');
  while (s.length % 4) s += '=';
  return new TextDecoder().decode(Uint8Array.from(atob(s), c => c.charCodeAt(0)));
}
